const lessonRows = entries.map(([stage,id,title,goal,tip,rawWords,model,modelEn])=>{
  const words=parseWords(rawWords), pick=words[0], type=words[1], third=words[2];
  const choices=[pick,...words.slice(1,4)].map(x=>x.fr);
  const grammar=grammarPractice[id];
  return {id,stage,title,goal,tip,words,
    tasks:[
      {kind:'choice',prompt:`Choose the French for “${pick.en}”.`,answer:pick.fr,choices,explanation:`${pick.fr} means “${pick.en}”.`},
      {kind:'type',prompt:`Translate into French: “${type.en}”.`,answer:type.fr,explanation:`The French phrase is ${type.fr}.`},
      {kind:'build',prompt:`Build this French sentence: “${modelEn}”`,answer:model,explanation:`${model} means “${modelEn}”.`},
      {kind:'choice',prompt:`Choose the French for “${third.en}”.`,answer:third.fr,choices:[third.fr,...words.filter(x=>x.fr!==third.fr).slice(0,3).map(x=>x.fr)],explanation:`${third.fr} means “${third.en}”.`},
      {kind:'choice',prompt:grammar[0],answer:grammar[1],choices:grammar[2],explanation:grammar[3]},
      {kind:'type',prompt:grammar[4],answer:grammar[5],explanation:`The constrained target phrase is “${grammar[5]}”.`}
    ]};
});
export const lessons=lessonRows;

const refItems=rows=>rows.map(([fr,en,note])=>({fr,en,note}));
